function startNewGame() {
  StateManager.newGame();
  initializePrices();

  // P2.11 新游戏+：检查并应用上局继承加成
  var ngApplied = false;
  try {
    var ngRaw = localStorage.getItem("_ngPlusData");
    if (ngRaw) {
      var ngData = JSON.parse(ngRaw);
      var state = StateManager.getState();
      if (ngData.startCash > 0) {
        state.resources.cash += ngData.startCash;
      }
      if (
        ngData.inheritSkill &&
        ngData.inheritSkillLevel > 0 &&
        state.skills[ngData.inheritSkill]
      ) {
        state.skills[ngData.inheritSkill].level = ngData.inheritSkillLevel;
      }
      if (ngData.statBonus > 0) {
        state.player.intelligence = Math.min(
          100,
          (state.player.intelligence || 0) + ngData.statBonus,
        );
        state.player.mental = Math.min(
          100,
          (state.player.mental || 0) + ngData.statBonus,
        );
      }
      // 携带声誉种子（未来事件可感知）
      if (ngData.reputationLabel) {
        state.flags._ngPlusReputation = ngData.reputationLabel;
      }
      state.flags._isNgPlus = true;
      localStorage.removeItem("_ngPlusData");
      ngApplied = true;
      var bonus =
        ngData.startCash > 0 ? "额外¥" + ngData.startCash + "启动资金" : "";
      var skillTxt = ngData.inheritSkill
        ? "、" +
          ngData.inheritSkill +
          "技能Lv." +
          ngData.inheritSkillLevel +
          "起步"
        : "";
      StateManager.addMessage(
        "🌟 新游戏+！你带着上局的经验重新出发：" +
          bonus +
          skillTxt +
          "。城市依然在等你。",
        "event",
      );
    }
  } catch (e) {}

  if (!ngApplied) {
    StateManager.addMessage(
      "🏘️ 你揣着1500元来到这座城市。欠村长5500元，日息0.35%复利。活下去，混出个人样来！",
      "event",
    );
  }
  StateManager.addMessage(
    '💡 提示：点击"🗺️ 地图"标签可查看城市全景。在城中村可以租房子、收废品。有了本钱可以去批发市场进货，再到商业区摆摊。',
    "info",
  );
  StateManager.addMessage(
    '🚶 点击行动页的"前往 XX"卡片或地图上的地点即可出行。左侧栏也有附近可前往的地点列表。',
    "info",
  );
  document.getElementById("welcome-screen").style.display = "none";
  document.getElementById("app").style.display = "";
  gameStarted = true;
  renderAll();
  if (typeof initCashCarousel === "function") initCashCarousel();

  // 新手引导（首次游戏）
  if (typeof startTutorial === "function") {
    setTimeout(() => startTutorial(), 300);
  }
}

function loadExistingGame(slot) {
  const saveData = loadGame(slot);
  if (saveData) {
    StateManager.importState(saveData);
    StateManager.addMessage("📂 存档已加载，欢迎回来！", "info");
    document.getElementById("welcome-screen").style.display = "none";
    document.getElementById("app").style.display = "";
    gameStarted = true;
    renderAll();
    if (typeof initCashCarousel === "function") initCashCarousel();
  }
}

/** 欢迎界面上显示存档选择 */
function showLoadMenuOnWelcome() {
  const allSlots = getAllSlotsWithEmpty();
  let bodyHtml = '<div style="max-height:400px;overflow-y:auto;">';
  for (const s of allSlots) {
    if (s.empty) {
      bodyHtml += `<div style="padding:8px;margin:4px 0;background:var(--bg-card);border-radius:4px;opacity:0.4;font-size:12px;color:var(--text-muted);">${s.label} — 空</div>`;
    } else {
      const phaseLabel = s.phase === "corporate" ? "🏢" : "🏘️";
      bodyHtml += `
        <div style="padding:10px;margin:4px 0;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;cursor:pointer;transition:all 0.2s;"
             onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'"
             onclick="document.querySelector('.modal-overlay')?.remove();loadExistingGame('${s.slot}')">
          <div style="display:flex;justify-content:space-between;align-items:center;">

